package net.civeira.phylax.feature.observe.observedprobe.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.valueobject.ExpectedTextVO;

@RequiredArgsConstructor
public class ExpectedTextValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<ExpectedTextVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param expectedText
   * @return
   */
  public T expectedText(ExpectedTextVO expectedText) {
    this.value = Optional.of(expectedText);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param expectedText
   * @return
   */
  public T expectedText(Optional<ExpectedTextVO> expectedText) {
    this.value = expectedText;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param expectedText
   * @return
   */
  public T expectedText(String expectedText) {
    this.value = Optional.of(ExpectedTextVO.from(expectedText));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T expectedTextNull() {
    this.value = Optional.of(ExpectedTextVO.nullValue());
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getExpectedText() {
    return value.flatMap(ExpectedTextVO::getExpectedText);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<ExpectedTextVO> getExpectedTextValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public ExpectedTextVO readExpectedText(final Optional<ObservedProbe> original,
      final ConstraintFailList fails) {
    return value.orElse(
        original.map(ObservedProbe::getExpectedTextValue).orElseGet(ExpectedTextVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetExpectedText() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetExpectedTextIfMatches(final String field) {
    if ("expectedText".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
